mapper.select:
select t.pcc_id pccId,t.machine_id machineId,t.shop_name shopName,t.coupon_shop_id couponShopId,t.status_cd
statusCd,t.shop_id shopId,t.community_id communityId,t.create_time createTime,pcs.pa_name paName,pc.`name` couponName
from parking_coupon_charge t
left join parking_coupon_shop pcs on t.coupon_shop_id = pcs.coupon_shop_id and pcs.status_cd = '0'
left join parking_coupon pc on pcs.coupon_id = pc.coupon_id and pc.status_cd = '0'
where 1 =1

    and t.pcc_id= #{pccId}


    and t.machine_id= #{machineId}


    and t.shop_name= #{shopName}


    and t.coupon_shop_id= #{couponShopId}


    and t.status_cd= #{statusCd}


    and t.shop_id= #{shopId}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

